from confluent_kafka import Consumer

c = Consumer({
    "bootstrap.servers": "kafka:9092",
    "group.id": "fraud-workers",
    "enable.auto.commit": False,
})

c.subscribe(["orders"])

while True:
    msg = c.poll(1.0)
    if msg is None:
        continue
    process(msg.value())
    c.commit(msg)
